import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, vec2, vec3, sin, fract, dot, smoothstep, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'pricing-card-2';

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const CARD_W = 2.6;
  const CARD_H = 3.4;
  const CARD_D = 0.09;

  const disposables = [];
  const timelines = [];

  // ---------- card body (brushed metal PBR) ----------
  const bodyGeo = new THREE.BoxGeometry(CARD_W, CARD_H, CARD_D);
  disposables.push(bodyGeo);

  const grainUv = uv().mul(900.0);
  const grainNoise = fract(sin(dot(grainUv, vec2(12.9898, 78.233))).mul(43758.5453));
  const grainSigned = grainNoise.sub(0.5).mul(0.045);

  const bodyMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.paper),
    roughness: 0.56,
    metalness: 0.5,
  });
  bodyMat.clearcoat = 0.2;
  bodyMat.clearcoatRoughness = 0.32;
  bodyMat.emissiveNode = vec3(grainSigned, grainSigned, grainSigned);
  disposables.push(bodyMat);

  const bodyMesh = new THREE.Mesh(bodyGeo, bodyMat);
  bodyMesh.position.set(0, 0, 0);
  group.add(bodyMesh);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
    tex.colorSpace = THREE.SRGBColorSpace;
    bodyMat.map = tex;
    bodyMat.needsUpdate = true;
  }).catch(() => {});

  // ---------- engineered gradient overlay (ink -> surface, vertical) ----------
  const overlayGeo = new THREE.PlaneGeometry(CARD_W - 0.02, CARD_H - 0.02);
  disposables.push(overlayGeo);

  const overlayMat = new MeshBasicNodeMaterial({ transparent: true });
  const gradTop = color(colors.ink);
  const gradBottom = color(colors.surface);
  overlayMat.colorNode = mix(gradTop, gradBottom, uv().y);
  overlayMat.opacityNode = smoothstep(0.0, 1.0, uv().y).mul(0.32).add(0.18);
  disposables.push(overlayMat);

  const overlayMesh = new THREE.Mesh(overlayGeo, overlayMat);
  overlayMesh.position.set(0, 0, CARD_D / 2 + 0.002);
  group.add(overlayMesh);

  // ---------- accent signal strip (top edge, <=10% of frame) ----------
  const accentGeo = new THREE.BoxGeometry(CARD_W, 0.045, CARD_D + 0.01);
  disposables.push(accentGeo);

  const accentMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.accent),
    roughness: 0.42,
    metalness: 0.3,
  });
  accentMat.emissive = new THREE.Color(colors.accent);
  accentMat.emissiveIntensity = 0.7;
  disposables.push(accentMat);

  const accentMesh = new THREE.Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, CARD_H / 2 - 0.03, 0.001);
  group.add(accentMesh);

  // ---------- contact shadow ----------
  const shadowGeo = new THREE.PlaneGeometry(CARD_W * 1.45, CARD_H * 0.5);
  disposables.push(shadowGeo);

  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  shadowMat.colorNode = color(colors.surface);
  const shCenter = uv().sub(vec2(0.5, 0.5));
  const shDist = length(shCenter);
  shadowMat.opacityNode = smoothstep(0.5, 0.0, shDist).mul(0.5);
  disposables.push(shadowMat);

  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -CARD_H / 2 - 0.55, -0.05);
  group.add(shadowMesh);

  // ---------- node-local rim / accent lights ----------
  const rimLight = new THREE.DirectionalLight(new THREE.Color(0xff8a6a), 0.75);
  rimLight.position.set(-2.2, 1.4, -1.6);
  group.add(rimLight);

  const accentGlow = new THREE.PointLight(new THREE.Color(colors.accent), 0.35, 3.5, 2.0);
  accentGlow.position.set(0, CARD_H / 2 - 0.03, 0.4);
  group.add(accentGlow);

  // ---------- entrance: weighted-settle ----------
  group.scale.setScalar(0.96);
  group.position.y += 0.14;
  const tl = gsap.timeline();
  tl.to(group.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.55,
    ease: 'power2.out',
  }).to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, '<0.05');
  tl.to(group.position, {
    y: group.position.y - 0.14,
    duration: 0.9,
    ease: 'power4.out',
  }, '<');
  timelines.push(tl);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    for (const t of timelines) {
      t.kill();
    }
    timelines.length = 0;

    group.remove(rimLight);
    group.remove(accentGlow);

    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') {
        d.dispose();
      }
    }
    if (bodyMat.map && typeof bodyMat.map.dispose === 'function') {
      bodyMat.map.dispose();
    }

    group.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
  };

  return group;
}
